/* PayZapp Recap 2026 themes.
   Pick one with ?theme=christmas|aurora|city|pixel (default: christmas).
   Artwork lives in assets/themes/<id>/ and is generated by build-theme-art.py
   (pixel: build-pixel-art.py, then node pixel-build/run.mjs for the card art). */
(function () {
    const THEMES = {
        christmas: {
            label: 'Christmas',
            base: '#0E3B2C',
            accent: '#FFD27A',
            ambient: 'snow',
            // Original card colour -> this theme's page colour behind the flipbook.
            colors: {
                '#0F4252': '#11402F', '#3F3313': '#5B1A26', '#0E3D4E': '#16384A',
                '#373A27': '#2F3D1F', '#3F2412': '#4E1E17', '#36255B': '#3D2040'
            }
        },
        aurora: {
            label: 'Night sky',
            base: '#0A1430',
            accent: '#8CF5CB',
            ambient: 'stars',
            colors: {
                '#0F4252': '#0C2F4A', '#3F3313': '#1D2758', '#0E3D4E': '#0A3A44',
                '#373A27': '#113A38', '#3F2412': '#2A1C4E', '#36255B': '#341F5E'
            }
        },
        city: {
            label: 'City lights',
            base: '#1B1235',
            accent: '#FFB86B',
            ambient: 'bokeh',
            colors: {
                '#0F4252': '#1B2452', '#3F3313': '#42213F', '#0E3D4E': '#12304A',
                '#373A27': '#2D2449', '#3F2412': '#4A1F2E', '#36255B': '#35205B'
            }
        },
        pixel: {
            label: 'Pixel-fi',
            base: '#3A24C8',
            accent: '#CDF34B',
            ambient: 'pixels',
            pixelate: true,
            summary: true,   // final page shows a bento of the correct answers
            colors: {
                // Page colour behind the flipbook: electric violets.
                '#0F4252': '#4329D6', '#3F3313': '#5B2BD0', '#0E3D4E': '#3530CC',
                '#373A27': '#4B27C2', '#3F2412': '#6A2BC4', '#36255B': '#4A23B4', '#2E2419': '#1E1852',
                // Question pages: lavender and blush instead of the original pastels.
                '#D6F4FF': '#EFE9FF', '#FFECB8': '#FCE6F7', '#E9EECE': '#F1F9D9',
                '#FFE1DB': '#FFE3F1', '#EED3F8': '#ECE2FF'
            }
        }
    };

    const requested = new URLSearchParams(location.search).get('theme');
    const id = Object.prototype.hasOwnProperty.call(THEMES, requested) ? requested : 'christmas';
    const theme = THEMES[id];
    const root = document.documentElement;
    root.dataset.theme = id;
    root.style.setProperty('--blue-dark', theme.base);
    root.style.setProperty('--theme-accent', theme.accent);

    const asset = name => `assets/themes/${id}/${name}`;
    const rand = (min, max) => Math.random() * (max - min) + min;

    function stars(container) {
        for (let i = 0; i < 46; i++) {
            const star = document.createElement('i');
            star.className = 'theme-star';
            const size = rand(1.2, 3.2);
            Object.assign(star.style, {
                left: `${rand(0, 100)}%`, top: `${rand(0, 72)}%`,
                width: `${size}px`, height: `${size}px`,
                animationDuration: `${rand(2.4, 5.5)}s`, animationDelay: `${rand(0, 5)}s`
            });
            container.appendChild(star);
        }
        for (let i = 0; i < 2; i++) {
            const meteor = document.createElement('i');
            meteor.className = 'theme-meteor';
            Object.assign(meteor.style, {
                left: `${rand(30, 90)}%`, top: `${rand(4, 30)}%`,
                animationDelay: `${2 + i * 5.5}s`
            });
            container.appendChild(meteor);
        }
        return true;
    }

    /* Pixel-fi: stepped-twinkle pixel sparkles and slow-drifting big pixels. */
    function pixels(container) {
        const sparkleColors = ['#FFFFFF', '#CDF34B', '#FF7AD0', '#7FE6FF'];
        for (let i = 0; i < 10; i++) {
            const s = document.createElement('i');
            s.className = 'theme-pixel-sparkle';
            s.style.color = sparkleColors[i % sparkleColors.length];
            s.style.setProperty('--px', `${[3, 3, 4][i % 3]}px`);
            Object.assign(s.style, {
                // Side gutters and the sky above the flipbook, never over the copy.
                left: `${i % 2 ? rand(1, 9) : rand(91, 98)}%`, top: `${rand(4, 60)}%`,
                animationDuration: `${rand(1.6, 3.2)}s`, animationDelay: `${rand(0, 3)}s`
            });
            container.appendChild(s);
        }
        const blockColors = ['#CDF34B', '#FF7AD0', '#A98BFF', '#7FE6FF'];
        for (let i = 0; i < 10; i++) {
            const b = document.createElement('i');
            b.className = 'theme-pixel-block';
            const size = [12, 18, 24][i % 3];
            Object.assign(b.style, {
                left: `${i % 2 ? rand(0, 7) : rand(93, 100)}%`, width: `${size}px`, height: `${size}px`,
                background: blockColors[i % blockColors.length],
                animationDuration: `${rand(14, 24)}s`, animationDelay: `${rand(-24, 0)}s`
            });
            container.appendChild(b);
        }
        return true;
    }

    function bokeh(container) {
        const colors = ['#FFD37A', '#FF8FB1', '#FFB86B', '#8FE3FF', '#FFFFFF'];
        for (let i = 0; i < 24; i++) {
            const light = document.createElement('i');
            light.className = 'theme-bokeh';
            const size = rand(6, 22);
            Object.assign(light.style, {
                left: `${rand(0, 100)}%`, width: `${size}px`, height: `${size}px`,
                background: colors[i % colors.length],
                animationDuration: `${rand(9, 18)}s`, animationDelay: `${rand(-18, 0)}s`
            });
            light.style.setProperty('--bokeh-opacity', rand(0.25, 0.6).toFixed(2));
            light.style.setProperty('--bokeh-drift', `${rand(-40, 40).toFixed(0)}px`);
            container.appendChild(light);
        }
        return true;
    }

    /* ---------------- Pixel-fi: prebuilt pixel art ----------------
       The pixel versions of the card art are made once at build time
       (pixel-build/run.mjs) into assets/themes/pixel/px/, with manifest.json mapping
       each original asset to its pixel file and, for card backgrounds, the colour of
       its top edge. Here we only swap paths: wherever the page shows an original
       asset, the pixel file is shown instead. Originals stay untouched. */
    const pixelMap = new Map();
    const topColors = new Map();
    const MANIFEST = 'assets/themes/pixel/px/manifest.json';

    function toHsl(hex) {
        const [r, g, b] = [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16) / 255);
        const max = Math.max(r, g, b), min = Math.min(r, g, b), l = (max + min) / 2;
        if (max === min) return [0, 0, l];
        const d = max - min, s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
        const h = max === r ? (g - b) / d + (g < b ? 6 : 0) : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
        return [h * 60, s, l];
    }
    function hslToHex(h, s, l) {
        const k = n => (n + h / 30) % 12, a = s * Math.min(l, 1 - l);
        const f = n => l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
        return '#' + [f(0), f(8), f(4)].map(v => Math.round(v * 255).toString(16).padStart(2, '0')).join('').toUpperCase();
    }
    const lightness = hex => (/^#[0-9a-f]{6}$/i.test(hex) ? toHsl(hex)[2] : 1);
    /* Same hue as the card art, pushed deep and saturated for the page behind it. */
    function deepShade(hex) {
        let [h, s] = toHsl(hex);
        // Dark yellows and greens turn olive; lean them toward amber and teal instead.
        if (h >= 38 && h < 75) h = 32;
        else if (h >= 75 && h < 140) h = 158;
        // Return hex, not hsl(): GSAP blends hsl() around the hue wheel (blue → green →
        // amber), while hex blends straight across in RGB.
        return hslToHex(h, Math.min(0.75, Math.max(0.55, s)), 0.28);
    }

    // Originals live directly in assets/; pixel files are under assets/themes/, which
    // this pattern never matches, so a swapped path is never swapped again.
    const ASSET_RE = /assets\/[\w-]+\.png/;
    const pixelFor = value => {
        const key = value && value.match(ASSET_RE);
        return key ? pixelMap.get(key[0]) : undefined;
    };
    function swapSrc(img) {
        const url = pixelFor(img.getAttribute('src'));
        if (url) img.src = url;
    }
    function swapBackground(el) {
        const url = el.style && pixelFor(el.style.backgroundImage);
        if (url) el.style.backgroundImage = `url("${url}")`;
    }
    function sweep(root) {
        if (root.matches?.('img')) swapSrc(root); else swapBackground(root);
        root.querySelectorAll?.('img[src*="assets/"]').forEach(swapSrc);
        root.querySelectorAll?.('[style*="assets/"]').forEach(swapBackground);
    }
    const ready = !theme.pixelate ? Promise.resolve() :
        fetch(MANIFEST).then(r => r.json()).then(manifest => {
            for (const [src, { file, top }] of Object.entries(manifest)) {
                pixelMap.set(src, file);
                if (top) topColors.set(src, top);
            }
            // Warm the cache for the card art so the first flips never wait.
            Object.values(manifest).forEach(({ file }) => { new Image().src = file; });
        }).catch(() => { /* Without the manifest the original art is shown. */ }).then(() => {
            sweep(document.documentElement);
            new MutationObserver(records => {
                for (const r of records) {
                    if (r.type === 'attributes') {
                        if (r.attributeName === 'src') swapSrc(r.target); else swapBackground(r.target);
                    } else {
                        r.addedNodes.forEach(n => { if (n.nodeType === 1) sweep(n); });
                    }
                }
            }).observe(document.documentElement, { subtree: true, childList: true, attributes: true, attributeFilter: ['src', 'style'] });
        });


    /* ---------------- Pixel-fi moments and 8-bit sound ----------------
       Pixel bursts and stepped shakes for answers, and chiptune blips made with Web
       Audio (square/triangle oscillators, no audio files). Other themes get no-ops
       and keep their original sounds. */
    const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
    const BURST_COLORS = ['#CDF34B', '#FF7AD0', '#7FE6FF', '#FFE45C', '#A98BFF', '#FFFFFF'];

    function burst(el) {
        if (reduceMotion || !window.gsap || !el) return;
        const r = el.getBoundingClientRect();
        const layer = document.createElement('div');
        layer.className = 'px-burst';
        document.body.appendChild(layer);
        for (let i = 0; i < 28; i++) {
            const bit = document.createElement('i');
            const size = [6, 8, 10][i % 3];
            Object.assign(bit.style, {
                width: `${size}px`, height: `${size}px`, background: BURST_COLORS[i % BURST_COLORS.length],
                left: `${r.left + r.width / 2 - size / 2}px`, top: `${r.top + r.height / 2 - size / 2}px`
            });
            layer.appendChild(bit);
            const angle = (Math.PI * 2 * i) / 28 + Math.random() * 0.3;
            const dist = 60 + Math.random() * 90;
            gsap.timeline()
                .to(bit, { x: Math.cos(angle) * dist, y: Math.sin(angle) * dist * 0.7 - 30, duration: 0.42, ease: 'steps(7)' })
                .to(bit, { y: `+=${80 + Math.random() * 80}`, opacity: 0, duration: 0.7, ease: 'steps(10)' });
        }
        setTimeout(() => layer.remove(), 1400);
    }

    function shake(el) {
        if (reduceMotion || !window.gsap || !el) return;
        el.style.transition = 'none';
        gsap.timeline({ onComplete: () => { el.style.transition = ''; gsap.set(el, { clearProps: 'x' }); } })
            .to(el, { x: -7, duration: 0.06, ease: 'steps(1)' })
            .to(el, { x: 7, duration: 0.06, ease: 'steps(1)' })
            .to(el, { x: -4, duration: 0.06, ease: 'steps(1)' })
            .to(el, { x: 4, duration: 0.06, ease: 'steps(1)' })
            .to(el, { x: 0, duration: 0.06, ease: 'steps(1)' });
    }

    let audio;
    function blips(notes, { type = 'square', step = 0.075, length = 0.07, volume = 0.06, slide = 0 } = {}) {
        try {
            audio = audio || new (window.AudioContext || window.webkitAudioContext)();
            if (audio.state === 'suspended') audio.resume();
            const start = audio.currentTime + 0.01;
            notes.forEach((freq, i) => {
                const osc = audio.createOscillator(), gain = audio.createGain();
                const t0 = start + i * step;
                osc.type = type;
                osc.frequency.setValueAtTime(freq, t0);
                if (slide) osc.frequency.exponentialRampToValueAtTime(freq * slide, t0 + length);
                gain.gain.setValueAtTime(volume, t0);
                gain.gain.setValueAtTime(volume, t0 + length * 0.7);
                gain.gain.exponentialRampToValueAtTime(0.0001, t0 + length);
                osc.connect(gain).connect(audio.destination);
                osc.start(t0);
                osc.stop(t0 + length + 0.02);
            });
            return true;
        } catch {
            return false;
        }
    }
    const SOUNDS = {
        correct: () => blips([523, 659, 784, 1047], { step: 0.07, length: 0.09 }),
        wrong: () => blips([311, 233], { step: 0.13, length: 0.14, volume: 0.05 }),
        flip: () => blips([880], { type: 'triangle', length: 0.09, volume: 0.08, slide: 0.45 }),
        start: () => blips([392, 784], { step: 0.06, length: 0.07 }),
        finale: () => blips([523, 659, 784, 1047, 784, 1047, 1319], { step: 0.085, length: 0.1, volume: 0.05 })
    };

    window.RecapTheme = {
        id,
        label: theme.label,
        summary: !!theme.summary,
        /* Theme moments: 'correct' / 'wrong' with the tapped element. No-op elsewhere. */
        moment(name, el) {
            if (id !== 'pixel') return;
            if (name === 'correct') burst(el);
            if (name === 'wrong') shake(el);
        },
        /* Plays a theme sound; returns true when handled so the original is skipped. */
        sound(name) {
            return id === 'pixel' && !document.hidden && SOUNDS[name] ? SOUNDS[name]() : false;
        },
        themes: Object.fromEntries(Object.entries(THEMES).map(([key, value]) => [key, value.label])),
        asset,
        /* Resolves once theme-specific art is ready (pixel art is generated at load). */
        ready,
        /* Maps an original card colour to this theme's. Page colours may name the card
           art they sit above; the pixel theme then uses that art's top-edge colour. */
        color: (original, art) => {
            const top = art && topColors.get(art);
            // Dark originals are page backgrounds: use a deep, saturated shade of the art.
            if (top) return lightness(original) < 0.4 ? deepShade(top) : top;
            return theme.colors[String(original).toUpperCase()] ||
                (String(original).toUpperCase() === '#183862' ? theme.base : original);
        },
        /* Fills the intro particle layer. Returns false to keep the original snowfall. */
        ambient(container) {
            if (theme.ambient === 'stars') return stars(container);
            if (theme.ambient === 'bokeh') return bokeh(container);
            if (theme.ambient === 'pixels') return pixels(container);
            return false;
        },
        /* Points themed <img data-theme-asset> elements at this theme's files. */
        apply(scope = document) {
            scope.querySelectorAll('img[data-theme-asset]').forEach(img => {
                img.src = asset(img.dataset.themeAsset);
            });
            const backdrop = document.getElementById('theme-backdrop');
            if (backdrop) backdrop.style.backgroundImage = `url("${asset('backdrop.svg')}")`;
        }
    };
    window.recapColor = window.RecapTheme.color;
})();
